import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

if (!process.env.AI_TRADING_DATA_DIR) {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ai-trading-test-'));
  process.env.AI_TRADING_DATA_DIR = tempDir;
  process.env.AI_TRADING_DB_PATH = path.join(tempDir, 'trading.db');

  process.once('exit', () => {
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch {}
  });
}

process.env.NODE_ENV = 'test';

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'fs';
import path from 'path';
import { reportingService } from '../src/services/reports/index.js';
import { backupService } from '../src/services/backup/index.js';
import { telegramService } from '../src/services/telegram/index.js';

test('Performance Reporting Engine & CSV Export', async (t) => {
  await t.test('generates valid performance report structure without crashing', () => {
    const report = reportingService.getPerformanceReport('all');

    assert.ok(report);
    assert.equal(typeof report.totalTrades, 'number');
    assert.equal(typeof report.winRatePercent, 'number');
    assert.equal(typeof report.netPnlIdr, 'number');
    assert.equal(typeof report.totalVolumeIdr, 'number');
    assert.ok(Array.isArray(report.coinBreakdown));
    assert.ok(Array.isArray(report.tradesList));
    assert.ok(report.aiEfficacy);
    assert.equal(typeof report.aiEfficacy.bulletsDodged, 'number');
  });

  await t.test('generates valid CSV string without tax calculations', () => {
    const csv = reportingService.generateCsv(30);

    assert.equal(typeof csv, 'string');
    assert.ok(csv.includes('No,ID Posisi,Waktu Beli,Waktu Jual,Simbol,Harga Beli (IDR)'));
    // Ensure tax headers are NOT included as specifically requested by user
    assert.ok(!csv.toLowerCase().includes('pajak'));
    assert.ok(!csv.toLowerCase().includes('pph'));
  });
});

test('Database Backup Service', async (t) => {
  await t.test('creates live online sqlite snapshot and lists backup items', async () => {
    const backup = await backupService.createBackup();

    assert.ok(backup);
    assert.ok(backup.filename.startsWith('trading_backup_'));
    assert.ok(backup.sizeBytes > 0);

    const list = backupService.getBackups();
    assert.ok(list.length > 0);
    assert.ok(list.some((b) => b.filename === backup.filename));

    // Verify backup file physically exists on disk
    const dataDir = process.env.AI_TRADING_DATA_DIR || path.resolve(process.cwd(), 'data');
    const backupPath = path.join(dataDir, 'backups', backup.filename);
    assert.ok(fs.existsSync(backupPath));
  });
});

test('Telegram Notifier Service', async (t) => {
  await t.test('handles missing or invalid credentials gracefully', async () => {
    const res = await telegramService.testConnection('', '');
    assert.equal(res.success, false);
    assert.ok(res.message.includes('wajib diisi'));
  });

  await t.test('sendAlert returns false when telegram is disabled', async () => {
    const sent = await telegramService.sendAlert('Test message');
    assert.equal(sent, false);
  });
});

import { db, getSetting } from '../../db/index.js';

export interface PerformanceSummary {
  periodLabel: string;
  startDate: string;
  endDate: string;
  currentMode: string;
  totalTrades: number;
  winningTrades: number;
  losingTrades: number;
  breakevenTrades: number;
  winRatePercent: number;
  totalVolumeIdr: number;
  grossProfitIdr: number;
  grossLossIdr: number;
  netPnlIdr: number;
  netPnlPercent: number;
  profitFactor: number | null;
  maxDrawdownPercent: number;
  maxDrawdownIdr: number;
  avgHoldDurationMinutes: number;
  bestTrade: {
    symbol: string;
    pnlIdr: number;
    pnlPercent: number;
    date: string;
  } | null;
  worstTrade: {
    symbol: string;
    pnlIdr: number;
    pnlPercent: number;
    date: string;
  } | null;
  coinBreakdown: Array<{
    symbol: string;
    tradesCount: number;
    wins: number;
    losses: number;
    winRatePercent: number;
    totalPnlIdr: number;
    avgPnlPercent: number;
  }>;
  aiEfficacy: {
    evaluationsCount: number;
    approvedCount: number;
    rejectedCount: number;
    bulletsDodged: number;
    savedCapitalIdr: number;
    opportunitiesMissed: number;
    missedProfitIdr: number;
  };
  lessonsLearned: Array<{
    id: string;
    symbol: string;
    result: string;
    pnl_percent: number;
    lesson: string;
    date: string;
  }>;
  tradesList: Array<{
    id: string;
    symbol: string;
    entry_price: number;
    exit_price: number;
    initial_cost_idr: number;
    amount: number;
    opened_at: number;
    closed_at: number;
    pnl_idr: number;
    pnl_percent: number;
    exit_reason: string;
    hold_minutes: number;
    mode: string;
  }>;
}

export class ReportingService {
  /**
   * Menghasilkan ringkasan laporan performa komprehensif untuk rentang waktu tertentu.
   */
  public getPerformanceReport(daysFilter: number | 'all' = 'all'): PerformanceSummary {
    const now = Date.now();
    let startTime = 0;
    let periodLabel = 'Semua Waktu';

    if (daysFilter !== 'all' && typeof daysFilter === 'number') {
      startTime = now - daysFilter * 24 * 60 * 60 * 1000;
      periodLabel = `${daysFilter} Hari Terakhir`;
    }

    // Ambil semua posisi yang ditutup dalam periode
    const query = startTime > 0
      ? db.prepare("SELECT * FROM positions WHERE status = 'closed' AND closed_at >= ? ORDER BY closed_at ASC")
      : db.prepare("SELECT * FROM positions WHERE status = 'closed' ORDER BY closed_at ASC");

    const positions = (startTime > 0 ? query.all(startTime) : query.all()) as any[];

    let totalVolumeIdr = 0;
    let grossProfitIdr = 0;
    let grossLossIdr = 0;
    let winningTrades = 0;
    let losingTrades = 0;
    let breakevenTrades = 0;
    let totalHoldMinutes = 0;

    let bestTrade: PerformanceSummary['bestTrade'] = null;
    let worstTrade: PerformanceSummary['worstTrade'] = null;

    // Track running equity curve for drawdown calculation
    let cumulativePnlIdr = 0;
    let peakCumulativePnlIdr = 0;
    let maxDrawdownIdr = 0;
    let maxDrawdownPercent = 0;

    const coinMap = new Map<string, {
      tradesCount: number;
      wins: number;
      losses: number;
      totalPnlIdr: number;
      sumPnlPercent: number;
    }>();

    const formattedTrades = positions.map((pos) => {
      const pnlIdr = pos.pnl_idr || 0;
      const pnlPct = pos.pnl_percent || 0;
      const holdMin = pos.closed_at ? Math.max(1, Math.round((pos.closed_at - pos.opened_at) / 60000)) : 0;
      totalHoldMinutes += holdMin;

      const tradeCost = pos.initial_cost_idr || 0;
      totalVolumeIdr += tradeCost * 2; // estimasi buy + sell volume

      if (pnlIdr > 0) {
        winningTrades++;
        grossProfitIdr += pnlIdr;
      } else if (pnlIdr < 0) {
        losingTrades++;
        grossLossIdr += Math.abs(pnlIdr);
      } else {
        breakevenTrades++;
      }

      // Best & Worst trade detection
      const closeDateStr = pos.closed_at ? new Date(pos.closed_at).toLocaleDateString('id-ID') : '-';
      if (!bestTrade || pnlIdr > bestTrade.pnlIdr) {
        bestTrade = {
          symbol: pos.symbol.toUpperCase(),
          pnlIdr,
          pnlPercent: pnlPct,
          date: closeDateStr,
        };
      }
      if (!worstTrade || pnlIdr < worstTrade.pnlIdr) {
        worstTrade = {
          symbol: pos.symbol.toUpperCase(),
          pnlIdr,
          pnlPercent: pnlPct,
          date: closeDateStr,
        };
      }

      // Cumulative Equity & Drawdown Tracker
      cumulativePnlIdr += pnlIdr;
      if (cumulativePnlIdr > peakCumulativePnlIdr) {
        peakCumulativePnlIdr = cumulativePnlIdr;
      }
      const currentDrawdownIdr = peakCumulativePnlIdr - cumulativePnlIdr;
      if (currentDrawdownIdr > maxDrawdownIdr) {
        maxDrawdownIdr = currentDrawdownIdr;
        const baseCapital = parseFloat(getSetting('paper_idr_balance', '10000000'));
        maxDrawdownPercent = (maxDrawdownIdr / (baseCapital + peakCumulativePnlIdr)) * 100;
      }

      // Per-coin aggregation
      const sym = pos.symbol.toUpperCase();
      const existingCoin = coinMap.get(sym) || { tradesCount: 0, wins: 0, losses: 0, totalPnlIdr: 0, sumPnlPercent: 0 };
      existingCoin.tradesCount++;
      if (pnlIdr > 0) existingCoin.wins++;
      else if (pnlIdr < 0) existingCoin.losses++;
      existingCoin.totalPnlIdr += pnlIdr;
      existingCoin.sumPnlPercent += pnlPct;
      coinMap.set(sym, existingCoin);

      return {
        id: pos.id,
        symbol: pos.symbol.toUpperCase(),
        entry_price: pos.entry_price,
        exit_price: pos.current_price,
        initial_cost_idr: pos.initial_cost_idr,
        amount: pos.amount,
        opened_at: pos.opened_at,
        closed_at: pos.closed_at,
        pnl_idr: pnlIdr,
        pnl_percent: pnlPct,
        exit_reason: pos.exit_reason || 'Manual Exit',
        hold_minutes: holdMin,
        mode: pos.mode,
      };
    });

    const totalTrades = positions.length;
    const netPnlIdr = grossProfitIdr - grossLossIdr;
    const winRatePercent = totalTrades > 0 ? (winningTrades / totalTrades) * 100 : 0;
    const profitFactor = grossLossIdr === 0 ? (grossProfitIdr > 0 ? null : 0) : parseFloat((grossProfitIdr / grossLossIdr).toFixed(2));
    const avgHoldDurationMinutes = totalTrades > 0 ? Math.round(totalHoldMinutes / totalTrades) : 0;

    const baseBalance = parseFloat(getSetting('paper_idr_balance', '10000000'));
    const netPnlPercent = baseBalance > 0 ? (netPnlIdr / baseBalance) * 100 : 0;

    // Convert Coin Map to Sorted Array
    const coinBreakdown = Array.from(coinMap.entries())
      .map(([symbol, c]) => ({
        symbol,
        tradesCount: c.tradesCount,
        wins: c.wins,
        losses: c.losses,
        winRatePercent: c.tradesCount > 0 ? parseFloat(((c.wins / c.tradesCount) * 100).toFixed(1)) : 0,
        totalPnlIdr: Math.round(c.totalPnlIdr),
        avgPnlPercent: c.tradesCount > 0 ? parseFloat((c.sumPnlPercent / c.tradesCount).toFixed(2)) : 0,
      }))
      .sort((a, b) => b.totalPnlIdr - a.totalPnlIdr);

    // AI Swarm Efficacy Metrics
    const evalQuery = startTime > 0
      ? db.prepare("SELECT ai_verdict FROM ai_ab_evaluations WHERE timestamp >= ?").all(startTime) as any[]
      : db.prepare("SELECT ai_verdict FROM ai_ab_evaluations").all() as any[];

    const evaluationsCount = evalQuery.length;
    const approvedCount = evalQuery.filter((e) => e.ai_verdict === 'APPROVED').length;
    const rejectedCount = evalQuery.filter((e) => e.ai_verdict === 'REJECTED').length;

    const ghostQuery = startTime > 0
      ? db.prepare("SELECT * FROM ghost_positions WHERE status = 'closed' AND closed_at >= ?").all(startTime) as any[]
      : db.prepare("SELECT * FROM ghost_positions WHERE status = 'closed'").all() as any[];

    let bulletsDodged = 0;
    let savedCapitalIdr = 0;
    let opportunitiesMissed = 0;
    let missedProfitIdr = 0;

    for (const g of ghostQuery) {
      if (g.simulated_outcome === 'BULLET_DODGED') {
        bulletsDodged++;
        savedCapitalIdr += Math.abs(g.pnl_idr || 0);
      } else if (g.simulated_outcome === 'OPPORTUNITY_MISSED') {
        opportunitiesMissed++;
        missedProfitIdr += g.pnl_idr || 0;
      }
    }

    // AI Lessons Learned
    const lessonsRaw = (
      startTime > 0
        ? db.prepare("SELECT * FROM lessons_learned WHERE timestamp >= ? ORDER BY timestamp DESC LIMIT 10").all(startTime)
        : db.prepare("SELECT * FROM lessons_learned ORDER BY timestamp DESC LIMIT 10").all()
    ) as any[];

    const lessonsLearned = lessonsRaw.map((l) => ({
      id: l.id,
      symbol: l.symbol.toUpperCase(),
      result: l.result,
      pnl_percent: l.pnl_percent,
      lesson: l.lesson,
      date: new Date(l.timestamp).toLocaleDateString('id-ID'),
    }));

    return {
      periodLabel,
      startDate: startTime > 0 ? new Date(startTime).toLocaleDateString('id-ID') : 'Awal',
      endDate: new Date(now).toLocaleDateString('id-ID'),
      currentMode: getSetting('trading_mode', 'paper').toUpperCase(),
      totalTrades,
      winningTrades,
      losingTrades,
      breakevenTrades,
      winRatePercent: parseFloat(winRatePercent.toFixed(1)),
      totalVolumeIdr: Math.round(totalVolumeIdr),
      grossProfitIdr: Math.round(grossProfitIdr),
      grossLossIdr: Math.round(grossLossIdr),
      netPnlIdr: Math.round(netPnlIdr),
      netPnlPercent: parseFloat(netPnlPercent.toFixed(2)),
      profitFactor,
      maxDrawdownPercent: parseFloat(maxDrawdownPercent.toFixed(2)),
      maxDrawdownIdr: Math.round(maxDrawdownIdr),
      avgHoldDurationMinutes,
      bestTrade,
      worstTrade,
      coinBreakdown,
      aiEfficacy: {
        evaluationsCount,
        approvedCount,
        rejectedCount,
        bulletsDodged,
        savedCapitalIdr: Math.round(savedCapitalIdr),
        opportunitiesMissed,
        missedProfitIdr: Math.round(missedProfitIdr),
      },
      lessonsLearned,
      tradesList: formattedTrades.reverse(), // Urutkan yang terbaru di atas
    };
  }

  /**
   * Menghasilkan teks CSV mentah siap unduh untuk Microsoft Excel / Google Sheets.
   */
  public generateCsv(daysFilter: number | 'all' = 'all'): string {
    const report = this.getPerformanceReport(daysFilter);
    const headers = [
      'No',
      'ID Posisi',
      'Waktu Beli',
      'Waktu Jual',
      'Simbol',
      'Harga Beli (IDR)',
      'Harga Jual (IDR)',
      'Modal Awal (IDR)',
      'Net Profit/Loss (IDR)',
      'Profit/Loss (%)',
      'Durasi (Menit)',
      'Alasan Exit',
      'Mode',
    ];

    const rows = report.tradesList.map((t, idx) => {
      const openDate = new Date(t.opened_at).toLocaleString('id-ID').replace(',', '');
      const closeDate = t.closed_at ? new Date(t.closed_at).toLocaleString('id-ID').replace(',', '') : '-';
      return [
        idx + 1,
        `"${t.id}"`,
        `"${openDate}"`,
        `"${closeDate}"`,
        `"${t.symbol}"`,
        t.entry_price,
        t.exit_price,
        Math.round(t.initial_cost_idr),
        Math.round(t.pnl_idr),
        t.pnl_percent.toFixed(2),
        t.hold_minutes,
        `"${t.exit_reason.replace(/"/g, '""')}"`,
        `"${t.mode.toUpperCase()}"`,
      ].join(',');
    });

    return [headers.join(','), ...rows].join('\r\n');
  }
}

export const reportingService = new ReportingService();

import Database from 'better-sqlite3';
import path from 'path';
import fs from 'fs';
import crypto from 'crypto';
import {
  decryptSecret,
  encryptSecret,
  isEncrypted,
  isSensitiveSettingKey,
} from '../services/security/secrets.js';

const dbPathEnv = process.env.AI_TRADING_DB_PATH;
export const DATA_DIR = process.env.AI_TRADING_DATA_DIR
  ? path.resolve(process.env.AI_TRADING_DATA_DIR)
  : path.resolve(process.cwd(), 'data');
const DB_PATH = dbPathEnv ? path.resolve(dbPathEnv) : path.join(DATA_DIR, 'trading.db');

const dbDir = path.dirname(DB_PATH);
if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true });
}

export const db = new Database(DB_PATH);

// Enable WAL mode and production performance PRAGMAs for concurrent reliability
db.pragma('journal_mode = WAL');
db.pragma('busy_timeout = 5000');
db.pragma('synchronous = NORMAL');
db.pragma('foreign_keys = ON');
db.pragma('cache_size = -64000');
db.pragma('temp_store = MEMORY');

let isDatabaseInitialized = false;

export function initDatabase() {
  if (isDatabaseInitialized) return;
  isDatabaseInitialized = true;

  db.exec(`
    CREATE TABLE IF NOT EXISTS providers (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      base_url TEXT NOT NULL,
      api_keys TEXT NOT NULL, -- JSON array of strings
      alias TEXT NOT NULL UNIQUE,
      protocol TEXT NOT NULL DEFAULT 'chat_completions', -- 'chat_completions' | 'messages' | 'antigravity'
      oauth_data TEXT, -- JSON object of OAuth tokens & metadata for Antigravity
      is_active INTEGER NOT NULL DEFAULT 1,
      created_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS models (
      id TEXT PRIMARY KEY,
      provider_id TEXT NOT NULL,
      model_id TEXT NOT NULL,
      alias_model_id TEXT NOT NULL UNIQUE, -- e.g. hrbr/deepseek-v3
      display_name TEXT NOT NULL,
      context_length INTEGER DEFAULT 128000,
      imported_at INTEGER NOT NULL,
      FOREIGN KEY (provider_id) REFERENCES providers (id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS positions (
      id TEXT PRIMARY KEY,
      symbol TEXT NOT NULL,
      base_currency TEXT NOT NULL,
      traded_currency TEXT NOT NULL,
      side TEXT NOT NULL DEFAULT 'buy',
      entry_price REAL NOT NULL,
      current_price REAL NOT NULL,
      amount REAL NOT NULL,
      initial_cost_idr REAL NOT NULL,
      highest_price REAL NOT NULL,
      trailing_stop_price REAL NOT NULL,
      take_profit_step INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL DEFAULT 'open', -- 'open' | 'closed'
      opened_at INTEGER NOT NULL,
      closed_at INTEGER,
      pnl_idr REAL DEFAULT 0,
      pnl_percent REAL DEFAULT 0,
      realized_pnl_idr REAL NOT NULL DEFAULT 0, -- net PnL already banked from partial exits
      exit_reason TEXT,
      mode TEXT NOT NULL DEFAULT 'paper' -- 'paper' | 'live'
    );

    CREATE TABLE IF NOT EXISTS trades_history (
      id TEXT PRIMARY KEY,
      position_id TEXT,
      symbol TEXT NOT NULL,
      type TEXT NOT NULL, -- 'BUY' | 'SELL'
      price REAL NOT NULL,
      amount REAL NOT NULL,
      total_idr REAL NOT NULL,
      fee_idr REAL NOT NULL DEFAULT 0,
      mode TEXT NOT NULL DEFAULT 'paper',
      order_id TEXT,
      reason TEXT,
      timestamp INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS subagent_logs (
      id TEXT PRIMARY KEY,
      agent_id TEXT NOT NULL,
      agent_name TEXT NOT NULL,
      source_name TEXT NOT NULL,
      title TEXT NOT NULL,
      summary TEXT NOT NULL,
      sentiment_score REAL NOT NULL,
      coins_mentioned TEXT, -- JSON array
      is_threat INTEGER NOT NULL DEFAULT 0,
      timestamp INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS lessons_learned (
      id TEXT PRIMARY KEY,
      trade_id TEXT,
      symbol TEXT NOT NULL,
      result TEXT NOT NULL, -- 'WIN' | 'LOSS'
      pnl_percent REAL NOT NULL,
      market_condition TEXT NOT NULL,
      lesson TEXT NOT NULL,
      timestamp INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS new_coin_alerts (
      id TEXT PRIMARY KEY,
      symbol TEXT NOT NULL UNIQUE,
      name TEXT NOT NULL,
      initial_price REAL NOT NULL,
      current_price REAL NOT NULL,
      volume_24h REAL NOT NULL,
      surge_percent REAL NOT NULL DEFAULT 0,
      detected_at INTEGER NOT NULL,
      status TEXT NOT NULL DEFAULT 'monitoring' -- 'monitoring' | 'entered' | 'ignored'
    );

    -- Persistent registry of every Indodax IDR pair ever observed.
    -- New-listing detection must compare against this, not against alert rows.
    CREATE TABLE IF NOT EXISTS known_pairs (
      pair_id TEXT PRIMARY KEY,
      first_seen_at INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS ai_ab_evaluations (
      id TEXT PRIMARY KEY,
      timestamp INTEGER NOT NULL,
      symbol TEXT NOT NULL,
      candidate_price REAL NOT NULL,
      technical_reason TEXT NOT NULL,
      sentiment_score REAL NOT NULL,
      threat_count INTEGER NOT NULL DEFAULT 0,
      ai_verdict TEXT NOT NULL, -- 'APPROVED' | 'REJECTED'
      ai_reasoning TEXT,
      mode TEXT NOT NULL DEFAULT 'paper'
    );

    CREATE TABLE IF NOT EXISTS ghost_positions (
      id TEXT PRIMARY KEY,
      evaluation_id TEXT,
      symbol TEXT NOT NULL,
      entry_price REAL NOT NULL,
      current_price REAL NOT NULL,
      highest_price REAL NOT NULL,
      trailing_stop_price REAL NOT NULL,
      take_profit_step INTEGER NOT NULL DEFAULT 0,
      initial_cost_idr REAL NOT NULL,
      amount REAL NOT NULL,
      opened_at INTEGER NOT NULL,
      closed_at INTEGER,
      pnl_idr REAL DEFAULT 0,
      pnl_percent REAL DEFAULT 0,
      exit_reason TEXT,
      status TEXT NOT NULL DEFAULT 'open', -- 'open' | 'closed'
      simulated_outcome TEXT, -- 'BULLET_DODGED' | 'OPPORTUNITY_MISSED'
      FOREIGN KEY (evaluation_id) REFERENCES ai_ab_evaluations (id) ON DELETE SET NULL
    );

    -- Entry Gate Diagnostics (Answers: "Mengapa bot belum trading?")
    CREATE TABLE IF NOT EXISTS entry_gate_logs (
      id TEXT PRIMARY KEY,
      ts INTEGER NOT NULL,
      symbol TEXT NOT NULL,
      gate_name TEXT NOT NULL, -- 'circuit_breaker' | 'exposure' | 'threat_scope' | 'btc_regime' | 'candidate_filter' | 'slippage' | 'spread' | 'rsi' | 'ai_gate' | 'score_threshold'
      passed INTEGER NOT NULL, -- 0 | 1
      values_json TEXT
    );

    -- AI Token Metering & Observability
    CREATE TABLE IF NOT EXISTS ai_call_logs (
      id TEXT PRIMARY KEY,
      ts INTEGER NOT NULL,
      agent TEXT NOT NULL, -- 'scout' | 'analyst' | 'master' | 'postmortem' | 'whatsapp'
      model TEXT,
      est_input_tokens INTEGER NOT NULL DEFAULT 0,
      est_output_tokens INTEGER NOT NULL DEFAULT 0,
      latency_ms INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL -- 'ok' | 'error' | 'skipped_dedup' | 'skipped_quota'
    );

    -- Structured News & Lexicon Scored Headlines
    CREATE TABLE IF NOT EXISTS news_items (
      id TEXT PRIMARY KEY, -- hash(source + title)
      source TEXT NOT NULL,
      title TEXT NOT NULL,
      url TEXT,
      published_at INTEGER,
      fetched_at INTEGER NOT NULL,
      sentiment_score REAL NOT NULL DEFAULT 0,
      matched_bullish TEXT,
      matched_bearish TEXT,
      mentioned_coins TEXT,
      is_threat INTEGER NOT NULL DEFAULT 0,
      threat_severity TEXT
    );

    -- Market Regime Audit Log
    CREATE TABLE IF NOT EXISTS regime_log (
      id TEXT PRIMARY KEY,
      ts INTEGER NOT NULL,
      regime TEXT NOT NULL,
      btc_change_1h_pct REAL,
      btc_change_4h_pct REAL,
      reasons TEXT
    );

    -- Opportunity Shortlist
    CREATE TABLE IF NOT EXISTS opportunity_shortlist (
      id TEXT PRIMARY KEY,
      ts INTEGER NOT NULL,
      symbol TEXT NOT NULL,
      strategy TEXT NOT NULL,
      score REAL NOT NULL,
      breakdown TEXT,
      consumed INTEGER NOT NULL DEFAULT 0
    );

    -- Multi-Agent Blackboard Bus Outbox
    CREATE TABLE IF NOT EXISTS agent_messages (
      id TEXT PRIMARY KEY,
      topic TEXT NOT NULL,
      from_agent TEXT NOT NULL,
      correlation_id TEXT,
      ts INTEGER NOT NULL,
      ttl_ms INTEGER NOT NULL,
      payload TEXT NOT NULL,
      consumed_by TEXT
    );

    -- Order Intent Journal (idempotency & crash recovery).
    -- Every live order writes an intent BEFORE the request is sent so a crash
    -- between "order sent" and "position recorded" can be resolved by querying
    -- the exchange with the client_order_id instead of guessing from balances.
    CREATE TABLE IF NOT EXISTS order_intents (
      id TEXT PRIMARY KEY,
      ts INTEGER NOT NULL,
      symbol TEXT NOT NULL,
      side TEXT NOT NULL, -- 'BUY' | 'SELL'
      kind TEXT NOT NULL, -- 'entry' | 'exit' | 'partial_tp' | 'panic' | 'derisk'
      order_type TEXT NOT NULL, -- 'MARKET' | 'LIMIT'
      params_json TEXT NOT NULL,
      position_id TEXT,
      client_order_id TEXT,
      state TEXT NOT NULL DEFAULT 'sent', -- 'sent' | 'ack' | 'resolved' | 'unresolved'
      exchange_order_id TEXT,
      resolved_at INTEGER,
      detail TEXT
    );

    -- Research candle cache (90-day ring buffer, written through whenever the
    -- engine observes candles). Backtests and walk-forward runs read from here.
    CREATE TABLE IF NOT EXISTS candles (
      pair TEXT NOT NULL,
      timeframe TEXT NOT NULL,
      ts INTEGER NOT NULL,
      open REAL NOT NULL,
      high REAL NOT NULL,
      low REAL NOT NULL,
      close REAL NOT NULL,
      volume REAL NOT NULL DEFAULT 0,
      PRIMARY KEY (pair, timeframe, ts)
    );

    -- High-Performance Secondary Indexes
    CREATE INDEX IF NOT EXISTS idx_positions_status ON positions(status);
    CREATE INDEX IF NOT EXISTS idx_positions_symbol_status ON positions(symbol, status);
    CREATE INDEX IF NOT EXISTS idx_positions_closed_at ON positions(closed_at);
    CREATE INDEX IF NOT EXISTS idx_ghost_positions_status ON ghost_positions(status);
    CREATE INDEX IF NOT EXISTS idx_trades_history_timestamp ON trades_history(timestamp DESC);
    CREATE INDEX IF NOT EXISTS idx_subagent_logs_timestamp ON subagent_logs(timestamp DESC);
    CREATE INDEX IF NOT EXISTS idx_lessons_learned_timestamp ON lessons_learned(timestamp DESC);
    CREATE INDEX IF NOT EXISTS idx_new_coin_alerts_status ON new_coin_alerts(status, detected_at DESC);
    CREATE INDEX IF NOT EXISTS idx_models_provider ON models(provider_id);
    CREATE INDEX IF NOT EXISTS idx_gate_logs_ts_sym ON entry_gate_logs(ts DESC, symbol);
    CREATE INDEX IF NOT EXISTS idx_gate_logs_gate ON entry_gate_logs(gate_name, passed);
    CREATE INDEX IF NOT EXISTS idx_ai_calls_ts ON ai_call_logs(ts DESC);
    CREATE INDEX IF NOT EXISTS idx_news_fetched ON news_items(fetched_at DESC);
    CREATE INDEX IF NOT EXISTS idx_news_threat ON news_items(is_threat, fetched_at DESC);
    CREATE INDEX IF NOT EXISTS idx_regime_ts ON regime_log(ts DESC);
    CREATE INDEX IF NOT EXISTS idx_shortlist ON opportunity_shortlist(ts DESC, consumed);
    CREATE INDEX IF NOT EXISTS idx_agent_messages_topic ON agent_messages(topic, ts DESC);
    CREATE INDEX IF NOT EXISTS idx_order_intents_state ON order_intents(state, ts DESC);
  `);

  // Safe migration for existing sqlite database: add oauth_data column if missing
  try {
    db.exec('ALTER TABLE providers ADD COLUMN oauth_data TEXT;');
  } catch {
    // Column already exists
  }

  // Exit claim prevents two concurrent flows (realtime tick, polling, panic sell)
  // from selling the same position twice.
  try {
    db.exec('ALTER TABLE positions ADD COLUMN exit_claimed_at INTEGER;');
  } catch {
    // Column already exists
  }

  try {
    db.exec('ALTER TABLE positions ADD COLUMN realized_pnl_idr REAL NOT NULL DEFAULT 0;');
  } catch {
    // Column already exists
  }

  // Timestamp when the position lost a guaranteed exit plan (sell failure,
  // balance ambiguity). NULL = protected (engine is actively managing an exit).
  try {
    db.exec('ALTER TABLE positions ADD COLUMN unprotected_since INTEGER;');
  } catch {
    // Column already exists
  }

  // Prompt version audit trail: which wording of a prompt produced this call.
  try {
    db.exec('ALTER TABLE ai_call_logs ADD COLUMN prompt_version TEXT;');
  } catch {
    // Column already exists
  }

  // Default configuration settings
  const defaultSettings: Record<string, string> = {
    trading_mode: 'paper', // default safe paper trading mode
    is_auto_trading_active: '0', // Default PAUSED as requested by user
    risk_profile: 'balanced', // 'conservative' | 'balanced' | 'aggressive'
