    }
    byAgent[r.agent].calls++;
    byAgent[r.agent].inputTokens += r.est_input_tokens;
    byAgent[r.agent].outputTokens += r.est_output_tokens;
  }

  return {
    totalCalls,
    totalInputTokens,
    totalOutputTokens,
    avgLatencyMs: totalCalls > 0 ? Math.round(totalLatency / totalCalls) : 0,
    byAgent,
    byStatus,
  };
}

